sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

          // Add your code here
	try {
        // Parse JSON passed in Parameter 1
     var details = JSON.parse(event.parm1);

        template.print("<h3>Jira Issue Updated</h3>");
        template.print("<table border='1' cellpadding='6' cellspacing='0' style='border-collapse:collapse;'>");


        template.print("<tr><td><b>Webhook Event</b></td><td>" + details.webhook_event + "</td></tr>");

        template.print("<tr><td><b>Issue ID</b></td><td>" + details.issue.id + "</td></tr>");
        template.print("<tr><td><b>Issue Key</b></td><td>" + details.issue.key + "</td></tr>");
        template.print("<tr><td><b>Issue Type</b></td><td>" + details.issue.type + "</td></tr>");

        template.print("<tr><td><b>Project ID</b></td><td>" + details.project.id + "</td></tr>");
        template.print("<tr><td><b>Project Key</b></td><td>" + details.project.key + "</td></tr>");
        template.print("<tr><td><b>Project Name</b></td><td>" + details.project.name + "</td></tr>");

        template.print("<tr><td><b>Sprint Name</b></td><td>" + details.sprint.name + "</td></tr>");
        template.print("<tr><td><b>Sprint State</b></td><td>" + details.sprint.state + "</td></tr>");
        template.print("<tr><td><b>Board ID</b></td><td>" + details.sprint.boardId + "</td></tr>");
        template.print("<tr><td><b>Sprint Goal</b></td><td>" + (details.sprint.goal || "N/A") + "</td></tr>");
        template.print("<tr><td><b>Start Date</b></td><td>" + (details.sprint.startDate || "N/A") + "</td></tr>");
        template.print("<tr><td><b>End Date</b></td><td>" + (details.sprint.endDate || "N/A") + "</td></tr>");

        template.print("</table>");

  // Build RITM URL
  var ritmUrl = gs.getProperty('glide.servlet.uri') +
     'sc_req_item.do?sys_id=' + current.getUniqueValue();

  template.print(
   "<b>RITM:</b> <a href='" + ritmUrl + "'>" +
   current.number +
   "</a><br/><br/>"
  );

    } catch (e) {

        template.print("<b>Error parsing event parameter:</b><br>");
        template.print(e.message + "<br><br>");

        template.print("<b>Raw Parameter 1:</b><br>");
        template.print(event.parm1);
    }

})(current, template, email, email_action, event);
